const e=[{id:"nikaya",title:"The Five Collections",note:"Pañcanikāya",description:"Read the five Nikāyas of the Sutta Piṭaka — Dīgha, Majjhima, Saṃyutta, Aṅguttara, and Khuddaka — with Pāli and study translations.",href:(a,t)=>`${a}/${t}/collection/nikaya`},{id:"abhidhamma",title:"The Higher Teaching",note:"Abhidhamma",description:"Explore the Abhidhamma Piṭaka, the Canon’s systematic analysis of mind, matter, and the path.",href:(a,t)=>`${a}/${t}/collection/abhidhamma`},{id:"vinaya",title:"The Discipline",note:"Vinaya",description:"Browse the Vinaya Piṭaka: the monastic rules, procedures, and origin stories of the Sangha.",href:(a,t)=>`${a}/${t}/collection/vinaya`},{id:"expositions",title:"The Expositions",note:"Aṭṭhakathā",description:"Open the Aṭṭhakathā, the classical expositions that explain the Tipiṭaka book by book.",href:(a,t)=>`${a}/${t}/collection/expositions`}];function h(a){return a==="commentaries"?e.find(t=>t.id==="expositions"):e.find(t=>t.id===a)}const o=["dīgha","digha","majjhima","saṃyutta","samyutta","aṅguttara","anguttara","khuddaka"];function s(a){return`${a.nikaya||""} ${a.subNikaya||""}`.toLowerCase()}function r(a,t){const i=s(a);return t==="nikaya"?i.includes("sutta")||o.some(n=>i.includes(n)):t==="abhidhamma"?i.includes("abhidhamma"):t==="vinaya"?i.includes("vinaya"):t==="expositions"||t==="commentaries"?a.category==="Aṭṭhakathā"||a.category==="Atthakatha":!1}export{e as C,r as b,h as c};
